sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    var adcard = {
    "type": "AdaptiveCard",
    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
    "version": "1.6",
    "body": [
        {
            "type": "Container",
            "items": [
                {
                    "type": "TextBlock",
                    "text": "Hi User- How are you",
                    "wrap": true
                }
            ]
        }
    ]
};

    var cardJSON = JSON.stringify(adcard);
template.print("Hello");
    template.print('<script type="application/adaptivecard+json">' + cardJSON + '</script>');

})(current, template, email, email_action, event);
